items=[]
for i,(strand,passage,prompt,correct,wrong,exp) in enumerate(rows):
    bank='practice' if i<48 else 'test'; n=i+1 if i<48 else i-47
    pos=(n-1)%4;opts=wrong[:];opts.insert(pos,correct)
    q=passage+'\n\n'+prompt
    items.append(dict(id=f'AC9E3LE04-{bank[0].upper()}-{n:03d}',subject='english',year_level='Year 3',curriculum_code='AC9E3LE04',bank=bank,stage='apply',skill='Effects of literary devices',question=q,audio_prompt=q,visual={'type':'none'},answers=[{'text':s,'is_correct':j==pos} for j,s in enumerate(opts)],correct_index=pos,explanation={'summary':exp,'hint':'Connect the effect to the exact words in this passage. For rhythm questions, read the marked pattern aloud.'},coverage_strand=strand,source={'creator':'SkillrHub original text','adaptation':'Newly authored poem or prose; no IXL or published literary text copied.'}))
# Eight genuine discussion responses; adult judgement must use passage evidence, not a fixed opinion.
open_tasks = {
40: ('Read the clock poem aloud. Explain how its repeated sound-words affect your sense of the wait.', 'Accept a link between tick-tock, repeated beats and the experience of waiting. A different personal reaction is acceptable if supported by those words.'),
41: ('Compare the quiet opening with the door slam. Explain why the sound-word changes the scene for you.', 'Look for the contrast between silence and the sudden loud bang. Do not require the learner to say they personally felt frightened.'),
42: ('Explain how the broom sound and the dust comparison help you imagine different parts of this scene.', 'Require both components: swish evokes brushing sound; the cloud comparison evokes rising dust. Accept equivalent everyday wording.'),
43: ('Read the creeping poem once with its pauses, then briskly without them. Discuss which reading better fits the sleeping dog, and explain why.', 'Look for an audible contrast and a reason linked to slow quiet movement and avoiding waking the dog. Exact timing is not required.'),
60: ('Explain how repeating “Not yet” shapes the moment before the curtain rises. Give a reason from the passage.', 'Accept anticipation, impatience or waiting when tied to the repeated phrase and the later curtain rise. Do not prescribe a single feeling.'),
61: ('Explain how “thirsty” and “drank” help you picture the garden receiving rain.', 'Accept a person-like need for water and taking in rain. Do not require the term personification, or accept a claim that the garden literally has a human mouth.'),
62: ('Describe the sound and picture created by the scissors poem. Refer to a different phrase for each.', 'Require cutting sound linked to snip and curled paper appearance linked to ribbon. No technical device labels are necessary.'),
63: ('Discuss the flag before and after the wind arrives. Explain how two words help you notice the change.', 'Look for limp as still or drooping, contrasted with woke or snapping as activity. Accept different reactions supported by this contrast.')
}
for index,(task,note) in open_tasks.items():
    item=items[index]
    item['question']=rows[index][1]+'\n\n'+task
    item['audio_prompt']=item['question']
    item.update(grading_mode='adult-review',answers=[],correct_index=None,model_answer=rows[index][5],acceptance_note=note,response_instructions='Share your response aloud with a partner or adult, or write two sentences. An adult checks the explanation against the supplied text.',completion_label='I shared my response aloud; an adult still needs to check it.')
